            667,667,667,722,667,667,722,778,389,500,667,611,889,722,722,611,722,667,556,611,722,667,889,667,611,611,
            333,278,333,570,500,333,
            500,500,444,500,444,333,500,556,278,278,500,278,778,556,500,500,500,389,389,278,556,444,667,500,444,389,
            348,220,348,570],
    ];

    /** Simbolos WinAnsi 0x80..0xBF (aproximados a partir de la familia). */
    private const ALTOS = [
        0x80=>'E', 0x82=>',', 0x83=>'f', 0x84=>'"', 0x85=>'M', 0x86=>'t', 0x87=>'t',
        0x88=>'^', 0x89=>'M', 0x8A=>'S', 0x8B=>'<', 0x8C=>'O', 0x8E=>'Z',
        0x91=>'\'', 0x92=>'\'', 0x93=>'"', 0x94=>'"', 0x95=>'.', 0x96=>'n', 0x97=>'M',
        0x98=>'~', 0x99=>'M', 0x9A=>'s', 0x9B=>'>', 0x9C=>'o', 0x9E=>'z', 0x9F=>'Y',
        0xA0=>' ', 0xA1=>'!', 0xA2=>'c', 0xA3=>'L', 0xA4=>'o', 0xA5=>'Y', 0xA6=>'|',
        0xA7=>'S', 0xA8=>'"', 0xA9=>'O', 0xAA=>'a', 0xAB=>'<', 0xAC=>'+', 0xAD=>'-',
        0xAE=>'O', 0xAF=>'-', 0xB0=>'o', 0xB1=>'+', 0xB2=>'1', 0xB3=>'1', 0xB4=>'\'',
        0xB5=>'u', 0xB6=>'P', 0xB7=>'.', 0xB8=>',', 0xB9=>'1', 0xBA=>'o', 0xBB=>'>',
        0xBC=>'M', 0xBD=>'M', 0xBE=>'M', 0xBF=>'?',
    ];

    /** Letras acentuadas 0xC0..0xFF -> letra base. */
    private const ACENTOS = [
        0xC0=>'A',0xC1=>'A',0xC2=>'A',0xC3=>'A',0xC4=>'A',0xC5=>'A',0xC6=>'W',0xC7=>'C',
        0xC8=>'E',0xC9=>'E',0xCA=>'E',0xCB=>'E',0xCC=>'I',0xCD=>'I',0xCE=>'I',0xCF=>'I',
        0xD0=>'D',0xD1=>'N',0xD2=>'O',0xD3=>'O',0xD4=>'O',0xD5=>'O',0xD6=>'O',0xD7=>'+',
        0xD8=>'O',0xD9=>'U',0xDA=>'U',0xDB=>'U',0xDC=>'U',0xDD=>'Y',0xDE=>'P',0xDF=>'b',
        0xE0=>'a',0xE1=>'a',0xE2=>'a',0xE3=>'a',0xE4=>'a',0xE5=>'a',0xE6=>'w',0xE7=>'c',
        0xE8=>'e',0xE9=>'e',0xEA=>'e',0xEB=>'e',0xEC=>'i',0xED=>'i',0xEE=>'i',0xEF=>'i',
        0xF0=>'o',0xF1=>'n',0xF2=>'o',0xF3=>'o',0xF4=>'o',0xF5=>'o',0xF6=>'o',0xF7=>'+',
        0xF8=>'o',0xF9=>'u',0xFA=>'u',0xFB=>'u',0xFC=>'u',0xFD=>'y',0xFE=>'p',0xFF=>'y',
    ];

    /** @return array<int,int> anchos por codigo de byte 0..255 */
    public static function widths(string $familia): array
    {
        $familia = strtolower($familia);
        if (strncmp($familia, 'courier', 7) === 0) {
            if (!isset(self::$cache['courier'])) self::$cache['courier'] = array_fill(0, 256, 600);
            return self::$cache['courier'];
        }
        if (isset(self::$cache[$familia])) return self::$cache[$familia];

        $base = self::ASCII[$familia] ?? null;
        if ($base === null) {
            // Oblicuas comparten metricas con su version recta
            $alias = str_replace(['-i', '-bi'], ['', '-b'], $familia);
            $base = self::ASCII[$alias] ?? self::ASCII['helvetica'];
        }
        $t = array_fill(0, 256, 500);
        foreach ($base as $i => $w) $t[32 + $i] = $w;
        foreach (self::ALTOS as $cod => $ref)   $t[$cod] = $t[ord($ref)] ?? 500;
        foreach (self::ACENTOS as $cod => $ref) $t[$cod] = $t[ord($ref)] ?? 500;
        // Ajustes de glifos anchos
        $t[0x85] = 1000; $t[0x89] = 1000; $t[0x97] = 1000; $t[0x99] = 1000; // ... ‰ — ™
        $t[0xBC] = $t[0xBD] = $t[0xBE] = (int)round($t[ord('0')] * 1.5);    // ¼ ½ ¾
        $t[0xC6] = (int)round($t[ord('A')] * 1.45);                          // Æ
        $t[0xE6] = (int)round($t[ord('a')] * 1.6);                           // æ
        self::$cache[$familia] = $t;
        return $t;
    }
}
